// nlcl_channels.cpp - channel factory.  This is the only translation unit that
// sees the OS socket headers (see nlcl_channels.hpp).  Generated by NLCL.
#include "nlcl_channels.hpp"

namespace nlcl {

std::unique_ptr<ChannelBase> makeChannel(const std::string& protocol, const std::string& id,
                                         const std::string& src, const std::string& dst,
                                         std::vector<std::string> fields, const Fields& config,
                                         bool localSrc, bool localDst) {
    std::unique_ptr<ChannelBase> ch;
    if (localSrc && localDst)
        ch.reset(new LocalChannel());  // both ends in this program: in-memory delivery
    else if (protocol == "http" || protocol == "websocket")
        ch.reset(new HubChannel());
    else if (protocol == "udp")
        ch.reset(new UdpChannel());
    else if (protocol == "mqtt")
        ch.reset(new MqttChannel());
    else
        ch.reset(new SerialChannel());  // serial/uart and electrical buses: JSON lines on stdio
    ch->id = id;
    ch->protocol = protocol;
    ch->src = src;
    ch->dst = dst;
    ch->fields = std::move(fields);
    ch->config = config;
    ch->localSrc = localSrc;
    ch->localDst = localDst;
    int ms = cfgInt(config, "interval_ms", 1000);
    ch->interval = (ms > 0 ? ms : 1000) / 1000.0;
    return ch;
}

}  // namespace nlcl
